import urwid
import sys

# Custom characters for LCD emulation
CHECKBOX_UNCHECKED = u'\u25A1'  # □
CHECKBOX_CHECKED = u'\u25A3'    # ▣
RADIO_UNSELECTED = u'\u25CB'    # ○
RADIO_SELECTED = u'\u25C9'      # ◉
PROGRESS_CHARS = [u'\u2591', u'\u2592', u'\u2593', u'\u2588']  # ░ ▒ ▓ █
SLIDER_LEFT = u'\u25C0'         # ◀
SLIDER_RIGHT = u'\u25B6'        # ▶
SLIDER_KNOB = u'\u25CF'         # ●
SLIDER_BG = u'\u2500'           # ─
MENU_ARROW = u'\u25B6'          # ▶

# Dummy LCD connection class for demonstration
class LCD635Connection:
    def __init__(self, port):
        self.port = port
    def set_brightness(self, value):
        pass
    def set_contrast(self, value):
        pass
    def set_cursor_style(self, style):
        pass
    def set_led_color(self, led, color):
        pass

# ProgressBar widget using custom characters
class CustomProgressBar(urwid.Widget):
    def __init__(self, current, total, width=16):
        self.current = current
        self.total = total
        self.width = width
    def set_value(self, value):
        self.current = value
        self._invalidate()
    def render(self, size, focus=False):
        width = min(self.width, size[0])
        frac = float(self.current) / self.total if self.total else 0
        full = int(frac * width)
        partial = int((frac * width - full) * (len(PROGRESS_CHARS)-1))
        text = ''
        for i in range(width):
            if i < full:
                text += PROGRESS_CHARS[-1]
            elif i == full and partial > 0:
                text += PROGRESS_CHARS[partial]
            else:
                text += PROGRESS_CHARS[0]
        return urwid.Text(text).render((width,))

# Horizontal slider using custom characters
class CustomSlider(urwid.WidgetWrap):
    def __init__(self, min_value, max_value, value, width=16, on_change=None):
        self.min = min_value
        self.max = max_value
        self.value = value
        self.width = width
        self.on_change = on_change
        self._update_widget()
    def _update_widget(self):
        pos = int((self.value - self.min) / float(self.max - self.min) * (self.width-2))
        slider = SLIDER_LEFT
        for i in range(self.width-2):
            if i == pos:
                slider += SLIDER_KNOB
            else:
                slider += SLIDER_BG
        slider += SLIDER_RIGHT
        self._w = urwid.Text(slider)
    def keypress(self, size, key):
        if key in ('left', 'h'):
            if self.value > self.min:
                self.value -= 1
                if self.on_change:
                    self.on_change(self.value)
                self._update_widget()
        elif key in ('right', 'l'):
            if self.value < self.max:
                self.value += 1
                if self.on_change:
                    self.on_change(self.value)
                self._update_widget()
        else:
            return key

# Custom CheckBox using one character
class CustomCheckBox(urwid.WidgetWrap):
    def __init__(self, label, state=False, on_state_change=None):
        self.state = state
        self.label = label
        self.on_state_change = on_state_change
        self._update_widget()
    def _update_widget(self):
        char = CHECKBOX_CHECKED if self.state else CHECKBOX_UNCHECKED
        self._w = urwid.AttrMap(urwid.Text(f"{char} {self.label}"), None, focus_map='reversed')
    def keypress(self, size, key):
        if key in ('enter', ' '):
            self.state = not self.state
            if self.on_state_change:
                self.on_state_change(self.state)
            self._update_widget()
        else:
            return key

# Custom RadioButton using one character
class CustomRadioButton(urwid.WidgetWrap):
    group = []
    def __init__(self, label, state=False, group=None, on_state_change=None):
        self.label = label
        self.state = state
        self.on_state_change = on_state_change
        if group is None:
            self.group = []
        else:
            self.group = group
        self.group.append(self)
        self._update_widget()
    def _update_widget(self):
        char = RADIO_SELECTED if self.state else RADIO_UNSELECTED
        self._w = urwid.AttrMap(urwid.Text(f"{char} {self.label}"), None, focus_map='reversed')
    def keypress(self, size, key):
        if key in ('enter', ' '):
            for btn in self.group:
                btn.state = False
                btn._update_widget()
            self.state = True
            if self.on_state_change:
                self.on_state_change(self.state)
            self._update_widget()
        else:
            return key

