class LEDColorSelector(urwid.WidgetWrap):
    COLORS = ['Red', 'Green', 'Blue', 'Yellow', 'Cyan', 'Magenta', 'White', 'Off']
    def __init__(self, led_num, current_color, on_change=None):
        self.led_num = led_num
        self.index = self.COLORS.index(current_color) if current_color in self.COLORS else 0
        self.on_change = on_change
        self._update_widget()
    def _update_widget(self):
        self._w = urwid.Text(f"LED {self.led_num}: {self.COLORS[self.index]}")
    def keypress(self, size, key):
        if key in ('left', 'h'):
            self.index = (self.index - 1) % len(self.COLORS)
            if self.on_change:
                self.on_change(self.led_num, self.COLORS[self.index])
            self._update_widget()
